"""Cross-check plan compilation (order, declarations, layout) on random types."""
import base64, json, random, struct, sys
sys.path.insert(0, '/workspace/project/src')
from eywa.offline import Campaign

INT_W = lambda bits: 1 if bits <= 8 else (2 if bits <= 16 else (4 if bits <= 32 else 8))

def make_decl(rng, names):
    kind = rng.choice(['bool', 'char', 'int', 'string', 'enum', 'array', 'struct', 'alias', 'void'])
    d = {'kind': kind}
    if kind == 'int': d['bits'] = rng.choice([1, 2, 7, 8, 9, 16, 17, 31, 32, 33, 64])
    if kind == 'string': d['maxsize'] = rng.randint(0, 4)
    if kind == 'enum': d['values'] = ['v%d' % i for i in range(rng.randint(1, 4))]
    if kind == 'array':
        d['element'] = rng.choice(names) if names else 'bool'
        d['size'] = rng.randint(0, 3)
    if kind == 'struct':
        d['fields'] = [[('f%d' % i), rng.choice(names) if names else 'bool']
                       for i in range(rng.randint(0, 3))]
    if kind == 'alias':
        d['target'] = rng.choice(names) if names else 'bool'
    return d

def ref_layout(decls, params, result, has_flag):
    """Independent layout implementation following PROTOCOL.md."""
    resolved = {}
    def resolve(name, stack=()):
        if name in resolved: return resolved[name]
        if name in stack: raise ValueError('cycle')
        d = decls[name]
        if d['kind'] == 'alias':
            inner = resolve(d['target'], stack + (name,))
            resolved[name] = ('alias', name, inner)
            return resolved[name]
        if d['kind'] == 'array':
            resolved[name] = ('array', name, resolve(d['element'], stack + (name,)), d['size'])
        elif d['kind'] == 'struct':
            resolved[name] = ('struct', name,
                              [(f, resolve(t, stack + (name,))) for f, t in d['fields']])
        else:
            resolved[name] = (d['kind'], name, d)
        return resolved[name]
    counter = [0]
    slots = []
    def leaf_width(kind, d):
        if kind in ('bool', 'char'): return 1
        if kind == 'enum': return 4
        if kind == 'int': return INT_W(d['bits'])
        raise AssertionError(kind)
    def reserve(node, path):
        kind, name, payload = node[0], node[1], node[2:]
        if kind == 'alias':
            return reserve(payload[0], path)
        if kind in ('bool', 'char', 'int', 'enum'):
            tag = 'x%d' % counter[0]; counter[0] += 1
            slots.append([tag, path, leaf_width(kind, payload[0])])
            return
        if kind == 'string':
            counter[0] += 1
            for i in range(payload[0]['maxsize']):
                reserve(('char', 'char', {'kind': 'char'}), path + [i])
            return
        if kind == 'array':
            counter[0] += 1
            for i in range(node[3]):
                reserve(payload[0], path + [i])
            return
        if kind == 'struct':
            counter[0] += 1
            for fname, ft in payload[0]:
                reserve(ft, path + [fname])
            return
        raise AssertionError(kind)
    declarations = []
    seen = set()
    def postorder(node):
        kind, name, payload = node[0], node[1], node[2:]
        if kind == 'alias':
            postorder(payload[0])
            if name not in seen: seen.add(name); declarations.append(name)
            return
        if kind == 'struct':
            for _f, ft in payload[0]: postorder(ft)
            if name not in seen: seen.add(name); declarations.append(name)
            return
        if kind == 'array':
            postorder(payload[0]); return
        if kind == 'enum':
            if name not in seen: seen.add(name); declarations.append(name)
            return
        return
    return resolve, reserve, postorder

rng = random.Random(int(sys.argv[1]) if len(sys.argv) > 1 else 0)
fails = 0
for trial in range(300):
    count = rng.randint(2, 9)
    names = []
    for i in range(count):
        base = 'T%d' % i
        names.append(base)
    decls = {}
    for i, name in enumerate(names):
        earlier = names[:i]
        decls[name] = make_decl(rng, earlier) if earlier else {'kind': rng.choice(['bool', 'int', 'char', 'string', 'enum'])}
        if decls[name]['kind'] in ('array', 'struct', 'alias') and not earlier:
            decls[name] = {'kind': 'int', 'bits': 8}
    # ensure a void type exists for results
    decls['Void'] = {'kind': 'void'}
    nparams = rng.randint(1, 4)
    param_types = [rng.choice(names + ['Void']) if rng.random() < 0.12 else rng.choice(names)
                   for _ in range(nparams)]
    result_type = rng.choice(names + ['Void'])
    has_flag = rng.random() < 0.5
    params = [['q%d' % i, t] for i, t in enumerate(param_types)]
    campaign = {
        'types': [dict({'name': k}, **v) for k, v in decls.items()],
        'modules': [{'name': 'app', 'params': params,
                     'result': ['out', result_type], 'requires': None}],
        'calls': [], 'pipes': [{'target': 'app', 'filter': 'app', 'bind': {}}] if has_flag else [],
        'entries': ['app'], 'machine': None, 'runs': []}
    try:
        cert = Campaign(campaign).certificate()
    except Exception as exc:
        # a parameter of void type or a cyclic declaration is out of domain
        continue
    plan = cert['plans'][0]
    # independent reference
    r_resolve, r_reserve, r_postorder = ref_layout(decls, params, result_type, has_flag)
    try:
        counter = [0]; slots = []
        for pname, ptype in params:
            r_reserve(r_resolve(ptype), [pname])
        if result_type != 'Void':
            r_reserve(r_resolve(result_type), ['out'])
        flag = None
        if has_flag:
            flag = 'x%d' % counter[0]; counter[0] += 1
        decls_out = []
        seen = set()
        def post(node):
            kind, name, payload = node[0], node[1], node[2:]
            if kind == 'alias':
                post(payload[0]); 
                if name not in seen: seen.add(name); decls_out.append(name)
                return
            if kind == 'struct':
                for _f, ft in payload[0]: post(ft)
                if name not in seen: seen.add(name); decls_out.append(name)
                return
            if kind == 'array':
                post(payload[0]); return
            if kind == 'enum':
                if name not in seen: seen.add(name); decls_out.append(name)
        for pname, ptype in params:
            post(r_resolve(ptype))
        if result_type != 'Void':
            post(r_resolve(result_type))
    except Exception:
        continue
    if plan['slots'] != slots or plan['flag'] != flag or plan['variables'] != counter[0] \
            or plan['types'] != decls_out:
        fails += 1
        print('MISMATCH trial', trial)
        print('  decls', json.dumps(campaign['types']))
        print('  params', params, 'result', result_type, 'flag', has_flag)
        print('  got slots ', plan['slots'])
        print('  want slots', slots)
        print('  got types', plan['types'], 'want', decls_out)
        print('  got flag/vars', plan['flag'], plan['variables'], 'want', flag, counter[0])
        if fails > 2: break
print('layout fuzz done, failures:', fails)
PYEOF
